/**
 * Zulangue 核心入口
 */
public protocol ZulangueCoreProtocol: AnyObject, Sendable {

    /**
     * 返回 API 版本号
     */
    func apiVersion()  -> String

    /**
     * 支持的 locale 列表。UI 用这个填语言 picker,避免 Swift 硬编码。
     */
    func availableLocales()  -> [String]

    /**
     * 删除 API Key(用户"移除配置"时调)。幂等。
     */
    func clearApiKey(scope: String) throws

    /**
     * Opens the one-shot durable task-worker gate after provider credentials
     * have either been restored successfully or cleared fail-closed.  This is
     * idempotent; it never exposes credential values.
     */
    func completeProviderCredentialBootstrap()

    /**
     * 当前 locale。用于诊断/验证桥接。
     */
    func currentLocale()  -> String

    /**
     * 销毁某个 session 的音频：删掉加密块，再删掉解得开它们的密钥。
     *
     * 销毁不看 `privacy_level`。等级决定音频**留多久**,不决定用户按下销毁时
     * 留下什么——留着密钥的"销毁"只是把明文推迟到下一次拿到密文的人手里。
     *
     * 流程：
     * 1. 安全覆写 + 删除每个加密音频块
     * 2. 删除 session 的密钥
     * 3. 清除 session_meta.encrypted_path
     */
    func destroySessionAudioAndKey(sessionId: String) throws

    /**
     * 获取默认隐私等级。
     */
    func getPrivacyDefault()  -> String

    /**
     * 获取会话信息（从 SQLite 查询）
     */
    func getSession(id: String) throws  -> SessionInfo

    /**
     * 检查某 scope 是否有 API Key(供 UI 显示"未配置"标记,不泄露 key 本身)。
     */
    func hasApiKey(scope: String)  -> Bool

    /**
     * 列出垃圾箱里的 session。TrashPage 专用。
     */
    func listTrashedSessions() throws  -> [SessionInfo]

    /**
     * 永久删除 session:清加密音频 + 密钥 + 从 session_records 删行。
     * 不可撤销。TrashPage 的 "Delete forever" 按钮调这个。
     */
    func purgeSession(sessionId: String) throws

    /**
     * 查询会话列表（带过滤/分页）
     */
    func querySessions(sessionType: String?, status: String?, searchText: String?, limit: UInt32?, offset: UInt32?) throws  -> SessionQueryResultInfo

    /**
     * 从垃圾箱恢复 session。
     */
    func restoreSession(sessionId: String) throws

    /**
     * 全文搜索会话。
     *
     * 垃圾箱里的录音不出现在结果里。软删只动 `session_records.deleted_at`,
     * 全文索引原样留着(恢复之后要能立刻搜回来),所以过滤在这里做:
     * 删掉的东西还能被搜出来,删除就成了障眼法。
     */
    func searchSessions(query: String, limit: UInt32) throws  -> [SearchResultInfo]

    /**
     * 设置进程内 API Key。
     *
     * 唯一支持的 scope 是 `soniox`。
     *
     * 空 value 视为 clear。
     */
    func setApiKey(scope: String, value: String) throws

    /**
     * 切换 Rust 端运行时 locale，影响所有 `CoreError` 文本。
     *
     * 传入 BCP-47 标签(`"zh-Hans"` / `"en"` / `"ja"` / `"zh-CN"` 等),
     * 经 [`vt_i18n::set_locale`] 规范化后生效。
     *
     * Swift 侧应在:
     * - 每次 App 启动时调用一次(根据 AppLanguage 设置)
     * - 用户在设置里切语言后立即调用
     */
    func setLocale(tag: String)

    /**
     * 设置默认隐私等级。
     *
     * 影响后续导入和 Notebook Capture 创建的 session。
     * 取值："standard" | "high" | "maximum"。无效值返回 ValidationFailed。
     */
    func setPrivacyDefault(level: String) throws

    /**
     * 关闭核心，释放资源;停掉 task worker 循环。
     * 在 flight 任务的状态会被 TaskQueue::new 启动时恢复为 pending。
     *
     * **先同步 flush 所有 editor snapshot 再 cancel worker** —— 兜底
     * `applicationWillTerminate` 漏调的情况。flush 自身失败不阻止 shutdown
     * (I/O 异常时 fs::write 只 log 不 propagate)。
     */
    func shutdown() throws

    /**
     * 软删单个 session。幂等:已软删再调是 no-op。
     * 正在录音的拒绝 —— 先停止,再删。
     */
    func softDeleteSession(sessionId: String) throws

    /**
     * 批量软删。部分不存在的 id 视为成功(幂等)。
     *
     * 名单里有正在录的,整批拒绝:悄悄跳过一条,用户会以为全删掉了。
     */
    func softDeleteSessions(sessionIds: [String]) throws

    /**
     * Verify a Soniox credential against the fixed realtime endpoint.
     *
     * A candidate value is verified before Settings or onboarding persists it.
     * Passing `None` verifies the active in-memory credential without exposing
     * that credential back across FFI. Credential material is never logged.
     */
    func verifyApiKey(scope: String, candidate: String?) async throws  -> FfiProviderConnectionCheck

    /**
     * 落盘并关闭。未打开时幂等成功。转录稿同时从 EditorBridge 撤下
     * ——bridge 挂载的生命周期与注册表句柄绑定,防止两边各持一份
     * 漂移的文档。
     */
    func blockDocumentClose(docId: String) throws

    /**
     * 打开(或按黄金祖先新建)一份块文档。幂等:已打开时校验 kind 后
