#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeZulangueCore: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = ZulangueCore

    public static func lift(_ handle: UInt64) throws -> ZulangueCore {
        return ZulangueCore(unsafeFromHandle: handle)
    }

    public static func lower(_ value: ZulangueCore) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ZulangueCore {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: ZulangueCore, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeZulangueCore_lift(_ handle: UInt64) throws -> ZulangueCore {
    return try FfiConverterTypeZulangueCore.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeZulangueCore_lower(_ value: ZulangueCore) -> UInt64 {
    return FfiConverterTypeZulangueCore.lower(value)
}




/**
 * Destruction receipt for one session's audio (FFI DTO).
 *
 * Every field is recomputed from the ledger, the filesystem, and the key
 * store at call time, so the UI can let the user re-verify "really deleted"
 * instead of trusting a cached flag.
 */
public struct AudioDestructionReportInfo: Equatable, Hashable {
    /**
     * Chunks the retention ledger ever recorded for this session.
     */
    public var chunkTotal: UInt32
    /**
     * Chunks the ledger marks as overwritten-and-deleted.
     */
    public var chunksDeleted: UInt32
    /**
     * Files that still exist on disk right now: recorded chunk paths plus a
