 *
 * 任何成功的 apply_edit 后 Rust 会查表找到注册了该 doc_id 的 callback,
 * 触发 on_doc_changed。Swift 侧在 LoroTextBridge 注册这个回调,
 * 收到通知后调 refreshFromDelta 把 NSTextView 同步成最新状态。
 *
 * 典型场景:
 * · 确定性 transcript projection 往 transcript doc 写入 — Swift UI 实时看到增长
 * · Swift 自己的编辑也会触发此回调 — 幂等刷新,suppressLoroSync
 * 保证不会产生反馈循环
 */
public protocol FfiEditorCallback: AnyObject, Sendable {

    /**
     * doc 内容发生变化(插入/删除/mark/unmark/replace 等)
     *
     * generation 单调递增,Swift 可用来对齐"上次同步到的版本"。
     */
    func onDocChanged(docId: String, generation: UInt64)

}


// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceFfiEditorCallback {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // This creates 1-element array, since this seems to be the only way to construct a const
    // pointer that we can pass to the Rust code.
    static let vtable: [UniffiVTableCallbackInterfaceFfiEditorCallback] = [UniffiVTableCallbackInterfaceFfiEditorCallback(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterCallbackInterfaceFfiEditorCallback.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface FfiEditorCallback: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterCallbackInterfaceFfiEditorCallback.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface FfiEditorCallback: handle missing in uniffiClone")
            }
        },
        onDocChanged: { (
            uniffiHandle: UInt64,
            docId: RustBuffer,
            generation: UInt64,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterCallbackInterfaceFfiEditorCallback.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.onDocChanged(
                     docId: try FfiConverterString.lift(docId),
                     generation: try FfiConverterUInt64.lift(generation)
                )
            }


            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )]
